const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function certificateState(sites,records,profile){const complete=sites.filter(s=>typeof records[s.id]?.done==='number'&&Number.isFinite(records[s.id].done)&&records[s.id].done>0),eligible=sites.length===25&&new Set(sites.map(s=>s.id)).size===25&&complete.length===25,earnedAt=eligible?Math.max(...complete.map(s=>records[s.id].done)):null;return{eligible,completed:complete.length,remaining:Math.max(0,25-complete.length),earnedAt,name:profile?.name||'',date:earnedAt?new Date(earnedAt).toLocaleDateString('ms-MY',{timeZone:'Asia/Kuching',day:'numeric',month:'long',year:'numeric'}):null};}
export function certificateSVG(sites,records,profile){const s=certificateState(sites,records,profile),name=String(s.name).trim();if(!s.eligible||Array.from(name).length<2||Array.from(name).length>24||/[\p{Cc}\p{Cf}]/u.test(name))throw Error('Certificate not ready');const fontSize=Array.from(name).length>18?39:49;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 848" width="1200" height="848" role="img" aria-label="Sijil pencapaian permainan untuk ${xml(name)}"><title>Sijil pencapaian permainan · ${xml(name)}</title><rect width="1200" height="848" fill="#fffdf5"/><path d="M0 0h1200v24H0ZM0 824h1200v24H0Z" fill="#234d38"/><rect x="33" y="48" width="1134" height="752" rx="3" fill="none" stroke="#b69a6c" stroke-width="2"/><rect x="43" y="58" width="1114" height="732" fill="none" stroke="#dce3d0"/><g fill="none" stroke="#d6dfc6" stroke-width="2"><path d="M55 232Q112 85 235 66M67 194q64 0 82-52M87 149q47 6 53-35M103 121q28-5 30-32M1144 613q-57 147-180 166M1132 651q-64 0-82 52M1112 696q-47-6-53 35M1096 724q-28 5-30 32"/></g><g transform="translate(574 93)"><rect width="52" height="52" rx="14" fill="#234d38"/><path d="m10 36 12-21 7 12 6-9 8 18Z" fill="none" stroke="#faf4e5" stroke-width="2.5" stroke-linejoin="round"/><circle cx="37" cy="13" r="3" fill="#c6a16b"/></g><g text-anchor="middle"><text x="600" y="185" font-family="Arial,sans-serif" font-size="17" font-weight="700" letter-spacing="5" fill="#234d38">JELAJAH GEOPARK LABUAN</text><text x="600" y="260" font-family="Georgia,serif" font-size="43" fill="#234d38">Sijil Pencapaian</text><text x="600" y="292" font-family="Arial,sans-serif" font-size="13" letter-spacing="3.5" fill="#87633f">PENGEMBARAAN DIGITAL · 25 PENEMUAN</text><path d="M410 318h380" stroke="#c5ac7d"/><text x="600" y="363" font-family="Arial,sans-serif" font-size="17" fill="#66765a">Diberikan kepada</text><text x="600" y="427" font-family="Georgia,serif" font-size="${fontSize}" font-weight="700" fill="#234d38">${xml(name)}</text><text x="600" y="474" font-family="Arial,sans-serif" font-size="17" fill="#5b6f50">kerana telah melengkapkan kesemua 25 misi permainan</text><text x="600" y="506" font-family="Arial,sans-serif" font-size="17" fill="#5b6f50">Jelajah Geopark Labuan dan memperoleh gelaran</text><text x="600" y="553" font-family="Georgia,serif" font-size="28" fill="#79583b">Penjaga Warisan Labuan</text><rect x="265" y="588" width="670" height="56" rx="9" fill="#edf3e4"/><text x="600" y="623" font-family="Arial,sans-serif" font-size="15" fill="#3d6038">11 GEOTAPAK  ·  4 BIOTAPAK  ·  10 TAPAK BUDAYA</text><text x="600" y="690" font-family="Arial,sans-serif" font-size="14" fill="#79583b">Tarikh tamat: ${xml(s.date)}</text><text x="600" y="727" font-family="Arial,sans-serif" font-size="12" fill="#6c7c5f">25 misi · 25 kad penemuan · 8 lencana permainan</text><text x="600" y="765" font-family="Arial,sans-serif" font-size="11" letter-spacing="1" fill="#7d8a71">SIJIL PENCAPAIAN PERMAINAN · JELAJAH GEOPARK LABUAN</text></g></svg>`;}
